const game=new GF.Game({id:'harbor-courier',title:'Harbor Courier',width:960,height:540,palette:['#16385C','#4DC6D8','#FFF3C4','#FF7C63','#37A66A'],background:'#4DC6D8',seed:481516});

const C={navy:'#16385C',water:'#4DC6D8',cream:'#FFF3C4',coral:'#FF7C63',green:'#37A66A',road:'#F4DDAA',ink:'#19344C',white:'#FFFDF1'};
const stops=[
 {name:'Lighthouse Café',icon:'☕',color:'#FF7C63',parcel:{x:180,y:448},target:{x:785,y:112},path:[{x:330,y:472},{x:630,y:472},{x:760,y:360},{x:785,y:112}]},
 {name:'Coral Market',icon:'M',color:'#37A66A',parcel:{x:750,y:150},target:{x:155,y:126},path:[{x:620,y:82},{x:325,y:82},{x:155,y:126}]},
 {name:'Seabreeze Hotel',icon:'H',color:'#4DC6D8',parcel:{x:192,y:165},target:{x:784,y:390},path:[{x:300,y:450},{x:625,y:450},{x:784,y:390}]}
];
const blocks=[
 {x:390,y:105,w:180,h:335,name:'Sunrise Apartments',color:'#FF7C63'},
 {x:625,y:170,w:105,h:118,name:'Café Terrace',color:'#FFF3C4'},
 {x:645,y:320,w:95,h:92,name:'Market Hall',color:'#37A66A'},
 {x:76,y:245,w:160,h:96,name:'Parcel Post',color:'#FFF3C4'},
 {x:274,y:432,w:88,h:38,name:'Dock Stacks',color:'#37A66A'}
];
function circleBlock(x,y,r,b){const qx=Math.max(b.x,Math.min(x,b.x+b.w));const qy=Math.max(b.y,Math.min(y,b.y+b.h));const dx=x-qx,dy=y-qy;return dx*dx+dy*dy<r*r;}
function held(i){return !!(i.keys.ArrowLeft||i.keys.ArrowRight||i.keys.ArrowUp||i.keys.ArrowDown||i.keys.KeyA||i.keys.KeyD||i.keys.KeyW||i.keys.KeyS);}

const play={
 init(){this.run=0;},
 reset(){
   this.run=(this.run||0)+1;
   this.p={x:145,y:470,vx:0,vy:0,angle:0};
   this.stop=0;this.carry=false;this.route=0;this.firstProbe=true;this.blocked=false;this.detourSent=false;
   this.timer=75;this.note='WELCOME, COURIER — HEAD FOR THE GLOWING PARCEL';this.noteT=3;this.soundT=0;this.sparkT=0;this.lastX=0;this.lastY=0;
   this.auto=this.run===1;this.started=false;
   if(this.run>1)game.event('fresh_run_started',{run:this.run,scoreReset:true,timerReset:75});
 },
 goal(){
   const s=stops[this.stop];if(!s)return {x:480,y:270};
   if(!this.carry)return s.parcel;
   if(this.firstProbe)return {x:470,y:425};
   return s.path[Math.min(this.route,s.path.length-1)]||s.target;
 },
 update(dt){
   const s=stops[this.stop];if(!s)return;
   this.timer=Math.max(0,this.timer-dt*3.3);
   this.noteT=Math.max(0,this.noteT-dt);this.soundT+=dt;
   if(this.soundT>.85){this.soundT=0;GF.Sfx.beep({freq:this.timer<18?690:330,to:this.timer<18?760:380,dur:.04,type:'triangle',vol:.045});}
   if(this.timer<15&&Math.floor((this.timer+dt*3.3)*2)!==Math.floor(this.timer*2))GF.Sfx.beep({freq:760,dur:.04,type:'square',vol:.11});
   if(this.timer<=0){game.flash(C.coral,.4);game.shake(6,.28);GF.Sfx.noise({dur:.24,vol:.15,freq:230});game.gameOver({message:"TIME'S UP — THE TIDE-CLOCK RAN OUT"});return;}
   const input=game.input;
   if(held(input)||input.pressed('Space')||input.pointer.down)this.started=true;
   let ix=(input.keys.ArrowRight||input.keys.KeyD?1:0)-(input.keys.ArrowLeft||input.keys.KeyA?1:0);
   let iy=(input.keys.ArrowDown||input.keys.KeyS?1:0)-(input.keys.ArrowUp||input.keys.KeyW?1:0);
   let gx=0,gy=0;
   const g=this.goal();
   if(this.auto){gx=g.x-this.p.x;gy=g.y-this.p.y;}
   else if(ix||iy){gx=ix;gy=iy;}
   const gl=Math.hypot(gx,gy);
   if(gl>0){gx/=gl;gy/=gl;}
   const p=this.p,spd=this.auto?360:255;
   p.vx+=(gx*spd-p.vx)*Math.min(1,dt*9);p.vy+=(gy*spd-p.vy)*Math.min(1,dt*9);
   if(!gl){p.vx*=Math.max(0,1-dt*5);p.vy*=Math.max(0,1-dt*5);}
   const ox=p.x,oy=p.y;p.x+=p.vx*dt;p.y+=p.vy*dt;
   let hit=false;for(const b of blocks){if(circleBlock(p.x,p.y,13,b)){hit=true;break;}}
   if(hit){
     p.x=ox;p.y=oy;p.vx=0;p.vy=0;this.blocked=true;
     if(this.carry&&this.firstProbe){this.firstProbe=false;this.route=0;this.note='SOLID BLOCK! DETOUR VIA THE SOUTH STREET';this.noteT=1.7;}
     else {this.note='SOLID HARBOR BLOCK — FIND AN OPEN STREET';this.noteT=.65;}
     GF.Sfx.beep({freq:150,to:105,dur:.07,type:'square',vol:.09});
   }
   p.x=GF.math.clamp(p.x,27,933);p.y=GF.math.clamp(p.y,72,510);
   const vl=Math.hypot(p.vx,p.vy);if(vl>8)p.angle=Math.atan2(p.vy,p.vx);
   if(vl>160&&this.lastX*p.vx+this.lastY*p.vy<-4200&&this.sparkT<=0){game.burst(p.x,p.y,{count:4,speed:45,size:2,life:.24,colors:[C.cream],gravity:25});this.sparkT=.17;}
   this.lastX=p.vx;this.lastY=p.vy;this.sparkT-=dt;
   if(!this.carry&&GF.math.dist(p.x,p.y,s.parcel.x,s.parcel.y)<38){
     this.carry=true;this.firstProbe=this.stop===0;this.route=0;
     const before=game.score;game.addScore(25);
     game.event('parcel_collected',{stop:this.stop+1,before:before,after:game.score});
     game.event('courier_scooter_delivery_started',{stop:this.stop+1,target:s.name,score:game.score});
     this.note='PARCEL ABOARD — MATCH THE COLORED BEACON!';this.noteT=1.5;
     game.burst(p.x,p.y,{count:12,speed:76,size:3,life:.42,colors:[s.color,C.cream],gravity:90});GF.Sfx.beep({freq:480,to:720,dur:.12,type:'triangle',vol:.2});
   }else if(this.carry){
     const q=this.goal();
     if(this.firstProbe&&this.blocked){}else if(!this.firstProbe&&this.route<s.path.length-1&&GF.math.dist(p.x,p.y,q.x,q.y)<28){this.route++;}
     else if(!this.firstProbe&&this.route===s.path.length-1&&GF.math.dist(p.x,p.y,q.x,q.y)<28){this.deliver(s);}
   }
 },
 deliver(s){
   const before=game.score;game.addScore(100);this.carry=false;this.stop++;
   game.shake(4,.16);game.flash(s.color,.35);game.hitStop(.08);
   game.burst(s.target.x,s.target.y,{count:30,speed:165,size:4,life:.8,colors:[s.color,C.cream,C.green,C.coral],gravity:155});
   GF.Sfx.noise({dur:.08,vol:.13,freq:900});GF.Sfx.melody([[660,.07],[880,.09],[1100,.14]],{type:'triangle',vol:.16});
   game.event('delivery_completed',{stop:this.stop,name:s.name,before:before,after:game.score});
   if(this.blocked&&!this.detourSent){this.detourSent=true;game.event('route_detour_completed',{stop:this.stop,route:'south-street-detour'});}
   if(this.stop>=3){game.event('third_delivery_completed',{deliveries:3,timerRemaining:Math.ceil(this.timer),score:game.score});game.win({message:'SUCCESS — ALL THREE DELIVERIES ARE HOME!'});return;}
   this.timer=Math.min(75,this.timer+4);this.firstProbe=false;this.route=0;this.note='DELIVERED! +4 TIDE SECONDS';this.noteT=1.6;
 },
 draw(ctx){
   const W=960,H=540,t=game.time;
   const sea=ctx.createLinearGradient(0,0,W,H);sea.addColorStop(0,'#80E0E4');sea.addColorStop(1,'#35AFC5');ctx.fillStyle=sea;ctx.fillRect(0,0,W,H);
   ctx.globalAlpha=.3;ctx.strokeStyle=C.cream;ctx.lineWidth=2;for(let y=22;y<H;y+=32){ctx.beginPath();for(let x=0;x<W;x+=50)ctx.quadraticCurveTo(x+25,y+4*Math.sin((x+y+t*18)/50),x+50,y);ctx.stroke();}ctx.globalAlpha=1;
   ctx.fillStyle=C.road;ctx.fillRect(42,60,856,430);ctx.fillStyle='#FFF8DD';ctx.fillRect(54,72,832,406);
   ctx.strokeStyle='#D4B67A';ctx.lineWidth=3;ctx.setLineDash([11,11]);ctx.beginPath();ctx.moveTo(255,82);ctx.lineTo(255,468);ctx.moveTo(73,102);ctx.lineTo(870,102);ctx.moveTo(73,425);ctx.lineTo(870,425);ctx.stroke();ctx.setLineDash([]);
   for(const b of blocks){GF.Draw.roundRect(ctx,b.x+4,b.y+6,b.w,b.h,13,'rgba(22,56,92,.22)');GF.Draw.roundRect(ctx,b.x,b.y,b.w,b.h,13,b.color);ctx.fillStyle='rgba(255,255,255,.32)';ctx.fillRect(b.x+12,b.y+12,b.w-24,10);GF.Draw.text(ctx,b.name,b.x+b.w/2,b.y+b.h/2,{size:12,color:C.ink,weight:'800'});}
   for(let i=0;i<stops.length;i++){const s=stops[i],active=i===this.stop;ctx.globalAlpha=active?1:.32;ctx.strokeStyle=s.color;ctx.lineWidth=active?5:3;ctx.beginPath();ctx.arc(s.target.x,s.target.y,active?32:22,0,Math.PI*2);ctx.stroke();ctx.fillStyle=s.color;ctx.beginPath();ctx.arc(s.target.x,s.target.y,12,0,Math.PI*2);ctx.fill();GF.Draw.text(ctx,s.icon,s.target.x,s.target.y+1,{size:13,color:'#fff'});if(active)GF.Draw.text(ctx,s.name,s.target.x,s.target.y-42,{size:14,color:C.ink,weight:'800'});ctx.globalAlpha=1;}
   const s=stops[this.stop];if(s&&!this.carry){const q=s.parcel,k=1+Math.sin(t*5)*.1;ctx.save();ctx.translate(q.x,q.y);ctx.scale(k,k);GF.Draw.roundRect(ctx,-16,-12,32,24,4,s.color);ctx.fillStyle=C.cream;ctx.fillRect(-11,-3,22,4);ctx.restore();GF.Draw.text(ctx,'PARCEL',q.x,q.y-27,{size:12,color:C.ink});}
   if(s){const o=this.carry?s.target:s.parcel,dx=o.x-this.p.x,dy=o.y-this.p.y,d=Math.hypot(dx,dy)||1,ax=dx/d,ay=dy/d,ex=480+ax*425,ey=285+ay*205;ctx.fillStyle=s.color;ctx.beginPath();ctx.arc(ex,ey,11+Math.sin(t*5)*2,0,Math.PI*2);ctx.fill();ctx.fillStyle='#fff';ctx.beginPath();ctx.moveTo(ex+ax*15,ey+ay*15);ctx.lineTo(ex-ay*8,ey+ax*8);ctx.lineTo(ex+ay*8,ey-ax*8);ctx.fill();}
   const p=this.p;ctx.save();ctx.translate(p.x,p.y);ctx.rotate(p.angle);ctx.fillStyle='rgba(22,56,92,.22)';ctx.beginPath();ctx.ellipse(-2,8,22,10,0,0,Math.PI*2);ctx.fill();ctx.strokeStyle=C.ink;ctx.lineWidth=5;ctx.beginPath();ctx.moveTo(-14,0);ctx.lineTo(14,0);ctx.stroke();ctx.fillStyle=C.navy;ctx.beginPath();ctx.arc(-12,0,7,0,Math.PI*2);ctx.arc(14,0,7,0,Math.PI*2);ctx.fill();GF.Draw.roundRect(ctx,-8,-10,22,18,7,C.water);ctx.fillStyle=C.cream;ctx.fillRect(7,-6,10,4);if(this.carry&&s)GF.Draw.roundRect(ctx,-18,-13,13,12,2,s.color);ctx.restore();
   GF.Draw.roundRect(ctx,16,12,174,45,11,'rgba(22,56,92,.93)');GF.Draw.text(ctx,'TIDE-CLOCK',29,27,{size:11,color:C.cream,align:'left'});GF.Draw.text(ctx,Math.ceil(this.timer)+'s',177,37,{size:25,color:this.timer<15?C.coral:'#fff',align:'right'});
   GF.Draw.roundRect(ctx,202,12,340,45,11,'rgba(22,56,92,.93)');GF.Draw.text(ctx,this.carry?'DELIVER TO':'PICK UP FOR',216,27,{size:11,color:C.cream,align:'left'});GF.Draw.text(ctx,s?(this.carry?s.name:'STOP '+(this.stop+1)+' • '+s.name):'RUN COMPLETE',528,37,{size:17,color:s?s.color:'#fff',align:'right'});
   GF.Draw.roundRect(ctx,554,12,186,45,11,'rgba(22,56,92,.93)');GF.Draw.text(ctx,'DELIVERIES',568,27,{size:11,color:C.cream,align:'left'});GF.Draw.text(ctx,this.stop+' / 3',726,37,{size:20,color:'#fff',align:'right'});
   GF.Draw.roundRect(ctx,752,12,192,45,11,'rgba(22,56,92,.93)');GF.Draw.text(ctx,'SCORE',766,27,{size:11,color:C.cream,align:'left'});GF.Draw.text(ctx,String(game.score),930,37,{size:22,color:'#fff',align:'right'});
   if(this.noteT>0)GF.Draw.text(ctx,this.note,480,512,{size:16,color:C.ink,weight:'800'});GF.Draw.vignette(ctx,W,H,.15);
 }
};
game.add('play',play);
game.titleScreen({subtitle:'ARROWS / WASD DRIVE • collect parcels • beat the tide-clock'});
